      splitMode: 'right',
      renderPreview: ({getValue}) => {
        const {html} = transform(getValue(), {breaks: true, linkify: true});

        return <div className=\"markdown-preview\" dangerouslySetInnerHTML={{__html: html}} />;
      },
    },
