        <h1 className=\"title\">Новая запись</h1>

        <div className=\"field\">
          <label className=\"field-label\" htmlFor=\"markdown-content\">
            Текст записи
          </label>
          <MarkdownEditorView stickyToolbar editor={editor} autofocus />
